/*
 * A064485  Number of ordered pairs a,b of elements in the dihedral group D_2n
 *          such that the subgroup generated by the pair a,b is a proper
 *          subgroup of D_2n.
 * https://oeis.org/A064485
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = 4*n^2 - 3*n*phi(n)
 * Range:     u8 n <= 9, u16 n <= 48, u32 n <= 48, u64 n <= 48, u128 n <= 48,
 *            big any n
 * Validated: partial, pass, 48 terms through n = 48 (2026-11-01)
 * Helpers:   totient
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include "../utils/totient.h"

seq_t a(idx_t n)
{
    seq_t ns = (seq_t)n;      /* convert index to seq_t */
    seq_t p  = totient(n);       /* Euler's totient φ(n) */
    return (seq_t)4 * ns * ns - (seq_t)3 * ns * p;
}
